import std/[syncio, assertions]
import std/crypto/[bignum, sha2]

proc hexVal(c: char): int =
  if c in {'0'..'9'}: ord(c) - ord('0')
  elif c in {'a'..'f'}: ord(c) - ord('a') + 10
  else: ord(c) - ord('A') + 10

proc unhex(s: string): seq[byte] =
  result = @[]
  var t = s
  if t.len mod 2 == 1: t = "0" & t
  var i = 0
  while i + 1 < t.len:
    result.add byte(hexVal(t[i]) * 16 + hexVal(t[i+1]))
    i += 2

proc big(s: string): BigNum =
  result = default(BigNum)
  if not fromBytesBE(unhex(s), result): quit "too big"

proc check(m, b, e, expected: string) =
  let mm = big(m)
  var ctx = default(Mont)
  if not initMont(mm, ctx): quit "bad modulus"
  let r = modExp(big(b), big(e), ctx)
  let want = big(expected)
  echo cmp(r, want) == 0

